'use strict';
const KEY='richard-endurance-v1', defaults={ftp:240,half:'2027-06-06',ultra:'2027-09-15',easy:'5:45–6:20',tempo:'5:00–5:15'};
let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{saved={}}
let state={settings:{...defaults,...saved.settings},logs:saved.logs||{},moves:saved.moves||{}};
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s+'T12:00:00'), iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, add=(s,n)=>{let d=date(s);d.setDate(d.getDate()+n);return iso(d)}, diff=(a,b)=>Math.round((date(a)-date(b))/86400000), monday=s=>add(s,-((date(s).getDay()+6)%7)), fmt=(s,opts={day:'numeric',month:'long'})=>date(s).toLocaleDateString('fr-FR',opts), duration=m=>m>=60?`${Math.floor(m/60)} h${m%60?' '+String(m%60).padStart(2,'0'):''}`:`${m} min`;
const today=iso(new Date()), start='2026-11-09', sports={swim:['≈','Natation'],bike:['↗','Vélo'],run:['↝','Course à pied'],strength:['＋','Renforcement'],rest:['○','Repos'],race:['⚑','Épreuve']};
let tab='today',selected=today,week=monday(today),plan=[];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Enregistrement indisponible : exporter une sauvegarde avant de fermer.')}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function phaseFor(s){const h=state.settings.half,u=state.settings.ultra,dh=diff(h,s),du=diff(u,s);if(s===h)return'Half des Lacs';if(s===u)return'Race Across · date provisoire';if(s>u)return'Récupération ultra';if(s>h&&diff(s,h)<=14)return'Récupération Half';if(s>h)return du<=12?'Affûtage ultra':du<=49?'Spécifique ultra':'Transition vers l’ultra';if(dh<=13)return'Affûtage Half';if(dh<=63)return'Spécifique Half';if(dh<=126)return'Construction';return'Fondations'}
function buildPlan(){plan=[];const ftp=state.settings.ftp,w=(a,b)=>`${Math.round(ftp*a)}–${Math.round(ftp*b)} W`,easy=()=>`${state.settings.easy} /km, priorité à une conversation aisée (RPE 2–3/10)`,tempo=()=>`${state.settings.tempo} /km provisoire, RPE 6/10 sans forcer l’allure`;
const block=(name,min,target,extra={})=>({name,min,target,...extra});
function push(s,sport,title,blocks,why,note=''){const id=s+'-'+sport+'-'+plan.filter(x=>x.original===s&&x.sport===sport).length;const history=state.logs[id];if(history?.done&&Array.isArray(history.blocks)){blocks=history.blocks;title=history.title||title}plan.push({id,original:s,date:state.moves[id]||s,sport,title,blocks,min:blocks.reduce((a,b)=>a+b.min,0),why,note,phase:phaseFor(s)})}
function bike(s,min,quality=false,specific=false){let blocks;if(quality){let n=specific?3:3,eff=specific?12:8,rest=3;const main=n*eff+(n-1)*rest;blocks=[block('Échauffement progressif',15,w(.5,.65),{power:.58})];for(let i=0;i<n;i++){blocks.push(block(`Bloc ${i+1}/${n}`,eff,w(specific?.78:.85,specific?.85:.92)+' · cadence naturelle 80–95 tr/min',{power:specific?.82:.88}));if(i<n-1)blocks.push(block('Récupération souple',rest,w(.45,.55),{power:.5}))}if(min-15-main-8>0)blocks.push(block('Endurance souple',min-15-main-8,w(.6,.7),{power:.65}));blocks.push(block('Retour au calme',8,w(.4,.5),{power:.45}));}
else blocks=[block('Mise en route',10,w(.45,.6),{power:.52}),block('Endurance régulière',min-20,w(.6,.72)+' · RPE 2–3, ne pas poursuivre les watts en cas de fatigue',{power:.66}),block('Retour au calme',10,w(.4,.5),{power:.45})];push(s,'bike',quality?(specific?'Tempo Half · position de course':'Tempo progressif · puissance'):min>=240?'Sortie longue · autonomie':'Endurance à vélo',blocks,quality?'Développer une puissance soutenable sans épuiser les réserves.':'Construire l’endurance et tester le confort, l’alimentation et la régularité.',min>=120?'Ravitaillement à pratiquer progressivement selon tolérance. Noter ce qui est mangé et bu, les arrêts et le confort. Sur route, watts indicatifs : sécurité et terrain prioritaires.':'Sur Wahoo : ventilation, boisson accessible et résistance adaptée. Les puissances sont basées sur une FTP ancienne, à réévaluer.');}
function pma(s,week){
if([3,7].includes(week)){bike(s,45);const x=plan[plan.length-1];x.title='Home trainer · récupération du bloc PMA';x.note+=' Semaine allégée : aucune répétition PMA.';return}
const short=week<3,reps=short?[6,8,10][week]:week===4?4:week===5?5:week===6?4:5,eff=short?.5:week<=5?2:3,power=short?1.2:1.1;
let blocks=[block('Échauffement · très facile',5,w(.45,.55),{power:.5}),block('Échauffement · endurance',10,w(.55,.7),{power:.63}),block('Préparation progressive',5,w(.7,.85)+' · sans sprint',{power:.75})];
if(short){for(let set=0;set<2;set++){for(let i=0;i<reps;i++){blocks.push(block(`Série ${set+1}/2 · effort ${i+1}/${reps}`,eff,w(1.15,1.25)+' · départ contrôlé, RPE 8–9/10 en fin de série',{power}));blocks.push(block('Récupération active',.5,w(.45,.55),{power:.5}))}if(set===0)blocks.push(block('Récupération entre séries',4,w(.45,.55),{power:.5}))}}
else for(let i=0;i<reps;i++){blocks.push(block(`PMA · répétition ${i+1}/${reps}`,eff,w(1.05,1.15)+' · viser des répétitions régulières, RPE 8–9/10',{power}));if(i<reps-1)blocks.push(block('Récupération active',eff,w(.45,.55),{power:.5}))}
let used=blocks.reduce((n,b)=>n+b.min,0);if(60-used-10>0)blocks.push(block('Endurance souple',60-used-10,w(.55,.65),{power:.6}));blocks.push(block('Retour au calme',10,w(.4,.5),{power:.45}));
push(s,'bike',short?`Home trainer · PMA 2 × ${reps} × 30″/30″`:`Home trainer · PMA ${reps} × ${eff} min`,blocks,'Développer la puissance aérobie avec une séance PMA/VO₂ par semaine, en remplacement du tempo.','Puissances provisoires calculées depuis la FTP, et non depuis une PMA mesurée. Commencer au bas de la plage. Réduire les watts ou le nombre de répétitions si la cadence ou la qualité se dégrade. Pas de sprint maximal. Ventilation et boisson accessibles. En ERG, la réaction sur 30 s peut être lente : préférer résistance/pente si nécessaire. Si fatigue inhabituelle, remplacer par 45 min faciles.');
}
function run(s,min,quality=false){let blocks;if(quality){blocks=[block('Échauffement facile',15,easy()),block('Tempo contrôlé',8,tempo(),{effort:1}),block('Récupération en trottinant',3,easy()),block('Tempo contrôlé',8,tempo(),{effort:1}),block('Retour au calme',min-34,easy())]}else blocks=[block('Départ très souple',min<=20?5:10,'RPE 2/10, sans cible de vitesse'),block('Endurance facile',min-(min<=20?10:15),easy()),block('Fin souple',5,'Relâcher, RPE 1–2/10')];push(s,'run',quality?'Tempo contrôlé · 2 × 8 min':min<=20?'Enchaînement vélo → course':min>=55?'Sortie longue · aisance':'Footing facile',blocks,quality?'Améliorer la tenue d’allure avec une fatigue maîtrisée.':'Consolider la régularité et l’endurance en course à pied.','Allures provisoires : le semi en 1 h 40 est ancien. En cas de dérive de l’effort, ralentir. Pas de rattrapage d’une séance manquée.');}
function swim(s,friday=false,light=false){push(s,'swim',friday?'Endurance & régularité':'Technique & économie',[block('Échauffement',10,'300–400 m souples, respiration libre'),block('Technique',10,'6 × 50 m : 25 m éducatif + 25 m nage complète ; 15–20 s de repos'),block(friday?'Série régulière':'Nage contrôlée',light?15:30,friday?'Répéter 200 m faciles, récupération 20 s. Rester relâché.':'Répéter 100 m en aisance, récupération 15–20 s ; 1′45″/100 m est un repère, pas une obligation.'),block('Retour au calme',10,'200–300 m souples puis mobilité douce si temps restant')],'Entretenir la technique et la capacité à nager de façon régulière.','Séance pilotée par le temps : arrêter la série principale à la fin du bloc, sans chercher à finir une distance imposée. Eau libre uniquement dans un cadre adapté et accompagné.');}
const end=add(state.settings.ultra,14);for(let s=start;s<=end;s=add(s,1)){const d=(date(s).getDay()+6)%7,idx=Math.floor(diff(s,start)/7),winter=s>='2026-11-30'&&s<='2027-01-31',winterWeek=Math.floor(diff(s,'2026-11-30')/7),cycle=winter?winterWeek%4:idx%4,light=cycle===3,ph=phaseFor(s),dh=diff(state.settings.half,s),du=diff(state.settings.ultra,s);
if(s===state.settings.half){push(s,'race','Half des Lacs · objectif 5 h',[block('Épreuve',300,'Objectif global, pas une prédiction de résultat')],'Exécuter une stratégie testée à l’entraînement.','Programme officiel : dimanche 6 juin 2027. Vérifier les dernières consignes de l’organisateur.');continue}
if(s===state.settings.ultra){push(s,'race','Race Across · 1 000 km / 12 000 D+',[block('Épreuve · jusqu’à 4 jours',5760,'96 h maximum, arrêts et sommeil inclus')],'Gérer l’effort, le ravitaillement, le sommeil et l’autonomie.','Date et destination à confirmer. Épreuve affichée sur le jour de départ ; les quatre jours sont réservés.');continue}
if(s>state.settings.ultra&&diff(s,state.settings.ultra)<4)continue;
if(s>state.settings.ultra||ph==='Récupération Half'){if(d===0||d===4)swim(s,d===4,true);if(d===2)run(s,25);if(d===6)bike(s,ph==='Récupération Half'&&diff(s,state.settings.half)>7?75:45);continue}
if(ph.startsWith('Affûtage')){let near=ph.includes('Half')?dh:du;if(near<=2){if(near===2)push(s,'bike','Activation souple',[block('Rouler facile',25,w(.45,.6),{power:.52})],'Garder de la mobilité sans accumuler de fatigue.');continue}if(d===0||d===4)swim(s,d===4,true);if(d===1)bike(s,near<=7?40:55);if(d===2)run(s,near<=7?25:35);if(d===5&&near>7)run(s,40);if(d===6&&near>7)bike(s,90);continue}
if(d===0||d===4)swim(s,d===4,light);
if([0,2,4].includes(d)){
const mins=light?10:d===0?20:15;
const titles={0:'Force contrôlée · jambes & dos',2:'Stabilité · gainage & unipodal',4:'Activation légère · mobilité'};
const circuits={0:'2 tours : 8 squats, 8 fentes par côté, 12 ponts fessiers, 10 tirages élastiques. Repos 30–45 s. Mouvement lent, sans échec musculaire.',2:'2 tours : 30 s de gainage frontal, 20 s latéral par côté, 8 bird-dogs par côté, 8 équilibres sur une jambe par côté. Repos 20–30 s.',4:'2 tours légers : 8 ponts fessiers, 10 élévations de mollets, 8 rotations thoraciques par côté et mobilité des hanches. RPE 2–3/10, aucune fatigue résiduelle recherchée.'};
push(s,'strength',titles[d],[block('Mise en route',3,'Mobilité douce des articulations sollicitées'),block(light?'Circuit allégé':'Circuit contrôlé',mins-5,circuits[d],{effort:!light&&d===0?1:0}),block('Relâchement',2,'Respiration et relâchement doux')],'Entretenir la force et le contrôle du mouvement.',light?'Semaine allégée : un seul tour, réduire les répétitions et rester facile.':'Séance courte après la séance principale ou dans un autre créneau. Le vendredi reste léger avant les sorties longues.');
}
if(ph==='Fondations'||ph==='Construction'||ph==='Spécifique Half'){const specific=ph==='Spécifique Half',construction=ph==='Construction',longBike=light?105:(specific?[180,195,210][cycle]:construction?[150,165,180][cycle]:[135,150,165][cycle]),longRun=light?50:(specific?[75,80,85][cycle]:construction?[65,70,75][cycle]:[55,60,65][cycle]);if(d===1){if(winter)pma(s,winterWeek);else bike(s,light?45:specific?75:60,!light&&(construction||specific||idx>=4),specific);}if(d===2)run(s,light?35:specific?50:45,!light&&(construction||specific)&&cycle===1);if(d===3)bike(s,light?35:45);if(d===5)run(s,longRun);if(d===6){bike(s,longBike,false,specific);if(specific&&!light&&cycle!==2)run(s,15)} }
else {const peak=ph==='Spécifique ultra',blockWeek=peak&&!light&&(cycle===1||cycle===2),long=light?150:peak?(blockWeek?300:270):[180,210,240][cycle];if(d===1)bike(s,light?45:60,!light);if(d===2)run(s,light?25:35);if(d===3)bike(s,35);if(d===5){if(blockWeek)bike(s,cycle===2?300:240);else run(s,light?35:45)}if(d===6){bike(s,long);if(blockWeek){let x=plan[plan.length-1];x.title='Bloc ultra · jour 2 sur fatigue';x.note+=' Enchaînement exceptionnel samedi + dimanche. Réduire si récupération insuffisante. Terrain vallonné, matériel chargé. Une sortie peut démarrer avant l’aube pour tester éclairage et vêtements ; conserver une vraie nuit de sommeil.'}}}
}
plan.forEach(x=>{if(x.sport==='bike'&&date(x.original).getDay()>=1&&date(x.original).getDay()<=5){x.location='Home trainer';if(!x.title.startsWith('Home trainer'))x.title='Home trainer · '+x.title;}else if(x.sport==='bike'){x.location='Extérieur';} });
plan.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));}

const intensityLevels=[{key:'blue',label:'Facile',description:'Endurance et récupération'},{key:'yellow',label:'Modérée',description:'Tempo contrôlé'},{key:'red',label:'Soutenue',description:'Travail au seuil'},{key:'purple',label:'Très intense',description:'Intervalles au-dessus du seuil'}];
function blockIntensity(b){if(Number.isFinite(b.effort))return Math.max(0,Math.min(3,b.effort));if(Number.isFinite(b.power))return b.power>=1.06?3:b.power>=.95?2:b.power>=.75?1:0;return 0}
function sessionIntensity(x){return Math.max(0,...x.blocks.map(blockIntensity))}
function intensityBadge(x){if(x.sport==='race')return '<span class="intensity-badge intensity-race">Épreuve</span>';const level=intensityLevels[sessionIntensity(x)];return `<span class="intensity-badge intensity-${level.key}">${level.label}</span>`}
function intensityLegend(){return `<div class="intensity-legend" aria-label="Légende des intensités">${intensityLevels.map(l=>`<span class="intensity-${l.key}" title="${l.description}"><i></i>${l.label}</span>`).join('')}</div><p class="intensity-help">Couleurs inspirées de Garmin. Intensité des blocs, pas durée de la séance ni mesure Garmin. Les niveaux rouge et violet apparaîtront uniquement si des blocs correspondants sont prescrits.</p>`}
function intensityStrip(x){return `<div class="intensity-strip" aria-label="Répartition de l’intensité par bloc">${x.blocks.map(b=>{const l=intensityLevels[blockIntensity(b)];return `<span class="intensity-${l.key}" style="flex:${Number(b.min)||1}" title="${esc(b.name)} : ${l.label} · ${blockDuration(b.min)}"></span>`}).join('')}</div>`}

function sessions(s){return plan.filter(x=>x.date===s)}function weekly(s){return plan.filter(x=>x.date>=s&&x.date<add(s,7))}function done(x){return state.logs[x.id]?.done}function card(x){return `<article class="card session intensity-${intensityLevels[sessionIntensity(x)].key} ${x.sport} ${done(x)?'complete':''}" role="button" tabindex="0" data-session="${x.id}" aria-label="Détail : ${esc(x.title)}"><div class="icon">${sports[x.sport][0]}</div><div class="info"><small>${sports[x.sport][1]}${x.location?' · '+x.location:''}${x.original!==x.date?' · déplacée':''}</small>${intensityBadge(x)}<h3>${esc(x.title)}</h3><p>${x.blocks[1]?esc(x.blocks[1].target.split(' · ')[0]):esc(x.blocks[0].target)}</p></div><div class="session-meta"><div class="duration">${duration(x.min)}</div>${intensityStrip(x)}</div><span class="arrow">↗</span></article>`}
function render(){const h=state.settings.half,u=state.settings.ultra;$('#ftpBadge').textContent=state.settings.ftp+' W';$('#halfLabel').textContent=fmt(h)+' 2027 · Troyes / Lusigny';$('#halfCount').textContent=diff(h,today)>=0?'J − '+diff(h,today):'Épreuve passée';$('#ultraLabel').textContent=fmt(u)+' · date provisoire';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let html='';if(tab==='today'){let a=sessions(selected),ws=weekly(monday(selected)),total=ws.filter(x=>x.sport!=='race').reduce((n,x)=>n+x.min,0);html=`<div class="sectionhead"><div><p class="todaydate">${fmt(selected,{weekday:'long',day:'numeric',month:'long'})}</p><h2>${selected===today?'Au programme aujourd’hui':'Votre programme'}</h2></div><span class="pill">${esc(phaseFor(selected))}</span></div>${a.map(card).join('')||`<div class="card empty"><h3>${selected<start?'Le plan démarre le 9 novembre':'Place à la récupération'}</h3><p class="muted">${selected<start?'Une première semaine progressive pour prendre les repères.':'Repos, marche douce ou mobilité selon les sensations.'}</p></div>`}<div class="actions"><button class="btn" id="prevDay">← Jour</button><button class="btn" id="goToday">Aujourd’hui</button><button class="btn" id="nextDay">Jour →</button>${selected<start?'<button class="btn primary" id="firstWeek">Voir la première semaine</button>':''}</div><div class="stats"><div><strong>${duration(total)}</strong><small>PRÉVU CETTE SEMAINE</small></div><div><strong>${ws.filter(done).length}/${ws.length}</strong><small>SÉANCES VALIDÉES</small></div><div><strong>${Math.floor(diff(selected,start)/7)+1>0?Math.floor(diff(selected,start)/7)+1:'—'}</strong><small>SEMAINE DU PLAN</small></div></div><div class="note">FTP et allures issues de repères anciens : les cibles restent provisoires. Pendant les deux premières semaines, privilégier l’aisance et noter les sensations. Réévaluer avant d’augmenter l’intensité.</div>`;}
if(tab==='week'){let ws=weekly(week),total=ws.filter(x=>x.sport!=='race').reduce((n,x)=>n+x.min,0);html=`<div class="sectionhead"><div><p class="eyebrow">DU ${fmt(week)} AU ${fmt(add(week,6))}</p><h2>${esc(phaseFor(add(week,3)))}</h2></div><div class="actions"><button class="btn" id="prevWeek" aria-label="Semaine précédente">←</button><button class="btn" id="nextWeek" aria-label="Semaine suivante">→</button></div></div><label class="datejump" for="jumpDate">Aller à une date<input id="jumpDate" type="date" min="${start}" max="${add(u,14)}" value="${week<start?start:week}"></label><div class="weekstrip">${Array.from({length:7},(_,i)=>{let s=add(week,i);return `<button class="daybutton ${s===selected?'selected':''}" data-day="${s}"><small>${fmt(s,{weekday:'short'})}</small><b>${date(s).getDate()}</b>${sessions(s).map(x=>`<span class="dot intensity-${intensityLevels[sessionIntensity(x)].key}" title="${esc(x.title)} · ${intensityLevels[sessionIntensity(x)].label}"></span>`).join('')}</button>`}).join('')}</div>${total>900?'<div class="note warning">Cette semaine dépasse 15 h après déplacement de séances. Répartir la charge avant de la suivre.</div>':''}<p class="lead">${duration(total)} d’entraînement · ${ws.length} séances · ${ws.filter(done).length} réalisées</p><div class="bar">${intensityLevels.map((l,i)=>`<span class="intensity-${l.key}" title="${l.label}" style="flex:${ws.filter(x=>x.sport!=='race').flatMap(x=>x.blocks).filter(b=>blockIntensity(b)===i).reduce((n,b)=>n+b.min,0)}"></span>`).join('')}</div>${Array.from({length:7},(_,i)=>{let s=add(week,i),a=sessions(s);return `<div class="daygroup"><h3>${fmt(s,{weekday:'long',day:'numeric',month:'short'})}</h3>${a.map(card).join('')||'<p class="muted">Repos / mobilité douce</p>'}</div>`}).join('')}<div class="note">Une séance manquée ne se rattrape pas automatiquement. Déplacer une séance ne rééquilibre pas la charge : conserver l’espace entre efforts exigeants. Les semaines allégées réduisent volontairement le volume.</div>`;}
if(tab==='season'){html=`<p class="eyebrow">DE NOVEMBRE À SEPTEMBRE</p><h2>La constance fait la distance.</h2><p class="lead">Un plan prévisionnel, à ajuster à tes retours et aux tests. Les dates des phases suivent les objectifs choisis.</p>${[['01','Fondations',`9 novembre → ${fmt(add(h,-127))}`,'Régularité, technique et endurance. Décembre–janvier : PMA sur home trainer le mardi, endurance facile sur home trainer le jeudi, sortie extérieure le dimanche. Deux cycles de trois semaines suivies d’une allégée, puis une séance de consolidation fin janvier.'],['02','Construction',`${fmt(add(h,-126))} → ${fmt(add(h,-64))}`,'Introduire le tempo contrôlé, prolonger les sorties sans augmenter toutes les disciplines à la fois. Réévaluer FTP et allures.'],['03','Spécifique Half',`${fmt(add(h,-63))} → ${fmt(add(h,-14))}`,'Position de course, tempo vélo soutenable, petits enchaînements et nutrition testée. L’endurance vélo prépare déjà l’ultra.'],['04','Affûtage & Half',`${fmt(add(h,-13))} → ${fmt(h)}`,'Réduire le volume pour arriver frais. Objectif 5 h à valider selon les tests, le parcours et les conditions ; aucun chrono garanti.'],['05','Récupération & transition',`${fmt(add(h,1))} → ${fmt(add(u,-50))}`,'Deux semaines de récupération puis hausse graduelle de la part du vélo ; maintien de la natation et de la course facile.'],['06','Spécifique ultra',`${fmt(add(u,-49))} → ${fmt(add(u,-13))}`,'Blocs ponctuels sur deux jours, dénivelé, autonomie et matériel chargé. Tests nocturnes sans privation volontaire de sommeil. Pics plafonnés à 15 h.'],['07','Affûtage & Race Across',`${fmt(add(u,-12))} → ${fmt(u)}`,'Baisser la charge, finaliser matériel, parcours, ravitaillements, sommeil et solutions de repli. Date provisoire au 15 septembre.']].map(([n,t,d,p])=>`<article class="phase"><b>${n}</b><div><small>${d}</small><h3>${t}</h3><p>${p}</p></div></article>`).join('')}<div class="card"><h3>Les repères à réévaluer</h3><p class="legend">Début de plan : 2 semaines de reprise observée, puis test FTP adapté à ton protocole habituel, en remplacement d’une séance vélo exigeante. Pas d’ajout de test à la charge prévue. Refaire un point en fin de fondations et avant le spécifique Half. Pour la course, commencer par observer un footing régulier et un tempo contrôlé avant de figer les allures.</p><p class="legend">Natation : 1′45″/100 m facile ne constitue pas une CSS mesurée. Le plan ne déduit pas automatiquement une allure seuil de ce repère.</p></div><div class="note">Les 1 000 km / 12 000 D+ / 96 h sont tes objectifs déclarés. Le lieu, la date et les règles exactes de ta Race Across restent à confirmer. Les sorties horaires ne garantissent pas un kilométrage ou un dénivelé.</div><p class="legend">Sources : <a href="https://troyes-tos-triathlon.fr/?page_id=1858" target="_blank" rel="noopener">Programme officiel des Lacs</a> · <a href="https://www.raceacrossseries.com/" target="_blank" rel="noopener">Race Across Series</a></p>`;}
if(tab==='settings'){html=`<h2>Ton terrain de jeu.</h2><p class="lead">Les réglages recalculent les séances futures et affichées. Les historiques réalisés restent dans le journal.</p><form id="settingsForm" class="card"><div class="grid"><div><label for="ftp">FTP provisoire · W</label><input id="ftp" name="ftp" type="number" min="100" max="500" required value="${state.settings.ftp}"></div><div><label for="half">Date du Half</label><input id="half" name="half" type="date" required value="${h}" min="2027-03-01" max="2027-07-01"></div><div><label for="ultra">Départ ultra · à confirmer</label><input id="ultra" name="ultra" type="date" required value="${u}" min="2027-08-15" max="2027-10-15"></div><div><label for="easy">Allure facile · min/km</label><input id="easy" name="easy" maxlength="40" required value="${esc(state.settings.easy)}"></div><div><label for="tempo">Tempo contrôlé · min/km</label><input id="tempo" name="tempo" maxlength="40" required value="${esc(state.settings.tempo)}"></div></div><p class="legend">Les allures proposées sont des estimations prudentes à partir d’un ancien semi en 1 h 40. L’aisance et l’effort perçu priment sur l’allure.</p><button class="btn primary" type="submit">Enregistrer mes repères</button></form><div class="card"><h3>Garmin Fenix 8 · course à pied</h3><p class="legend">Cette version fournit les blocs détaillés et une fiche à copier. Elle ne se connecte pas à ton compte Garmin et n’envoie pas automatiquement les séances.</p><ol class="legend"><li>Garmin Connect → Plus → Entraînement et planification → Entraînements → Créer → Course à pied.</li><li>Reproduire les durées et cibles de la fiche de séance.</li><li>Enregistrer → Envoyer vers l’appareil → Fenix 8, puis synchroniser.</li></ol><a href="https://www8.garmin.com/manuals/webhelp/GUID-EECCAC99-90D6-4AB1-9A3A-EC433D3365E2/FR-FR/GUID-D6E80F0C-F319-47D1-AF95-0884F3386635.html" target="_blank" rel="noopener">Mode d’emploi Garmin ↗</a></div><div class="card"><h3>Suivi & sauvegarde</h3><p class="legend">Les validations, déplacements et sensations sont enregistrés dans ce navigateur. Ils ne se synchronisent pas entre appareils. Exporter une sauvegarde pour les conserver ou les transférer.</p><div class="actions"><button class="btn" id="backup">Exporter ma sauvegarde</button><button class="btn" id="restore">Restaurer</button><button class="btn" id="calendar">Calendrier .ics</button></div><input type="file" id="importFile" accept="application/json" hidden></div><div class="note">Cadre : vélo en semaine sur home trainer ; sortie extérieure le dimanche (blocs ultra du samedi conservés). Décembre–janvier : PMA le mardi, jeudi facile. Nage lundi et vendredi ; renforcement lundi, mercredi et vendredi (hors affûtage et récupération) ; course longue samedi ; vélo long dimanche. En période ultra, certains samedis deviennent des journées vélo. Pas de connexion aux données Garmin ni d’ajustement automatique de charge.</div>`;}
$('#content').innerHTML=(['today','week'].includes(tab)?intensityLegend():'')+html;bind();}
function validSettings(t){return t&&Number.isFinite(Number(t.ftp))&&Number(t.ftp)>=100&&Number(t.ftp)<=500&&/^2027-\d\d-\d\d$/.test(t.half)&&iso(date(t.half))===t.half&&t.half>='2027-03-01'&&t.half<='2027-07-01'&&/^2027-\d\d-\d\d$/.test(t.ultra)&&iso(date(t.ultra))===t.ultra&&t.ultra>='2027-08-15'&&t.ultra<='2027-10-15'&&diff(t.ultra,t.half)>=45&&typeof t.easy==='string'&&typeof t.tempo==='string'}
function bind(){document.querySelectorAll('[data-session]').forEach(e=>{e.onclick=()=>openSession(e.dataset.session);e.onkeydown=k=>{if(k.key==='Enter'||k.key===' '){k.preventDefault();openSession(e.dataset.session)}}});if($('#jumpDate'))$('#jumpDate').onchange=e=>{if(e.target.value){selected=e.target.value;week=monday(selected);render()}};const click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn};click('firstWeek',()=>{selected=start;week=start;tab='week';render()});click('prevDay',()=>{selected=add(selected,-1);render()});click('nextDay',()=>{selected=add(selected,1);render()});click('goToday',()=>{selected=today;render()});click('prevWeek',()=>{week=add(week,-7);render()});click('nextWeek',()=>{week=add(week,7);render()});document.querySelectorAll('[data-day]').forEach(e=>e.onclick=()=>{selected=e.dataset.day;tab='today';render()});if($('#settingsForm'))$('#settingsForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);const next={ftp:Number(f.get('ftp')),half:f.get('half'),ultra:f.get('ultra'),easy:f.get('easy'),tempo:f.get('tempo')};if(!validSettings(next))return toast('Vérifier les dates et conserver 45 jours entre les objectifs');state.settings=next;persist();buildPlan();render();toast('Repères enregistrés')};click('backup',()=>download('endurance-richard-sauvegarde.json',JSON.stringify(state,null,2),'application/json'));click('restore',()=>$('#importFile').click());if($('#importFile'))$('#importFile').onchange=async e=>{try{let t=JSON.parse(await e.target.files[0].text());if(!validSettings(t.settings)||!t.logs||typeof t.logs!=='object'||Array.isArray(t.logs)||!t.moves||typeof t.moves!=='object'||Array.isArray(t.moves)||Object.values(t.moves).some(v=>typeof v!=='string'||!/^202[67]-\d\d-\d\d$/.test(v)||iso(date(v))!==v||v<start||v>add(t.settings.ultra,14)))throw Error();state={settings:{...defaults,...t.settings},logs:t.logs||{},moves:t.moves||{}};persist();buildPlan();render();toast('Sauvegarde restaurée')}catch{toast('Sauvegarde non reconnue')}};click('calendar',calendarExport);}
function blockDuration(min){return min<1?Math.round(min*60)+' s':duration(min)}
function sessionText(x){return `${x.title}\n${fmt(x.date)} · ${duration(x.min)}\n\n${x.blocks.map((b,i)=>`${i+1}. ${b.name} · ${blockDuration(b.min)}\n${b.target}`).join('\n\n')}\n\n${x.note}`}
function openSession(id){const x=plan.find(a=>a.id===id),log=state.logs[id]||{};$('#detailBody').innerHTML=`<button class="close" id="closeDetail" aria-label="Fermer">×</button><p class="eyebrow">${sports[x.sport][1]} · ${fmt(x.date)}</p><h2>${esc(x.title)}</h2><p class="lead">${x.location?x.location+' · ':''}${duration(x.min)} · ${esc(x.phase)}</p>${intensityBadge(x)}${intensityStrip(x)}<p>${esc(x.why)}</p>${x.blocks.map((b,i)=>`<div class="block intensity-${intensityLevels[blockIntensity(b)].key}"><span class="num">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(b.name)}</strong><span class="block-intensity">${intensityLevels[blockIntensity(b)].label}</span><p>${esc(b.target)}</p></div><time>${blockDuration(b.min)}</time></div>`).join('')}<div class="note">${esc(x.note||'Adapter à tes sensations du jour.')}</div>${x.sport==='run'?'<p class="legend">Garmin : reproduire ces blocs dans Connect → Entraînements → Course à pied, puis envoyer à la Fenix 8. Pas de synchronisation automatique.</p>':''}<div class="actions"><button class="btn" id="copySession">Copier la fiche</button>${x.sport==='bike'?'<button class="btn" id="zwoExport">Exporter vélo .zwo</button>':''}</div><form id="logForm"><label for="feel">Effort ressenti · 1 très facile → 10 maximal</label><input id="feel" name="feel" type="number" min="1" max="10" value="${esc(log.feel||'')}" placeholder="Ex. 4"><label for="notes">Sensations, fatigue, ravitaillement</label><textarea id="notes" name="notes" maxlength="2000" placeholder="Ce qui a bien fonctionné, ce qui est à adapter…">${esc(log.notes||'')}</textarea><div class="actions"><button class="btn primary" type="submit">${log.done?'Mettre à jour':'Valider la séance'}</button><button class="btn" id="uncheck" type="button">Marquer non faite</button></div></form><label for="moveDate">Déplacer cette séance</label><div class="actions"><input id="moveDate" type="date" value="${x.date}" min="${start}" max="${add(state.settings.ultra,14)}"><button class="btn" id="moveSession">Déplacer</button></div><p class="legend">Le déplacement est manuel : pas de compensation ni de recalcul automatique des autres séances.</p>`;$('#detail').showModal();$('#closeDetail').onclick=()=>$('#detail').close();$('#copySession').onclick=async()=>{try{await navigator.clipboard.writeText(sessionText(x));toast('Fiche copiée')}catch{download(x.id+'.txt',sessionText(x),'text/plain')}};if($('#zwoExport'))$('#zwoExport').onclick=()=>zwo(x);$('#logForm').onsubmit=e=>{e.preventDefault();state.logs[id]={done:true,feel:$('#feel').value,notes:$('#notes').value,title:x.title,date:x.date,minutes:x.min,blocks:x.blocks};persist();$('#detail').close();render();toast('Séance enregistrée')};$('#uncheck').onclick=()=>{state.logs[id]={...log,done:false,feel:$('#feel').value,notes:$('#notes').value};persist();$('#detail').close();render()};$('#moveSession').onclick=()=>{const v=$('#moveDate').value;if(!v||v<start||v>add(state.settings.ultra,14))return toast('Choisir une date dans le plan');state.moves[id]=v;persist();buildPlan();$('#detail').close();render();toast('Séance déplacée')};}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function zwo(x){const xml=`<?xml version="1.0" encoding="UTF-8"?><workout_file><author>Richard Endurance</author><name>${esc(x.title)}</name><description>FTP de référence ${state.settings.ftp} W. Vérifier la FTP dans la plateforme avant la séance.</description><sportType>bike</sportType><workout>${x.blocks.map(b=>`<SteadyState Duration="${b.min*60}" Power="${b.power||.6}"/>`).join('')}</workout></workout_file>`;download(x.id+'.zwo',xml,'application/xml');toast('Export .zwo · plateforme compatible requise')}
function calendarExport(){let clean=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Richard Endurance//FR','CALSCALE:GREGORIAN'];plan.forEach(x=>rows.push('BEGIN:VEVENT','UID:'+x.id+'@richard-endurance','DTSTAMP:'+today.replaceAll('-','')+'T120000Z','DTSTART;VALUE=DATE:'+x.date.replaceAll('-',''),'DTEND;VALUE=DATE:'+add(x.date,x.title.startsWith('Race Across')?4:1).replaceAll('-',''),'SUMMARY:'+clean(x.title+' · '+duration(x.min)),'DESCRIPTION:'+clean(sessionText(x)),'END:VEVENT'));rows.push('END:VCALENDAR');const encoder=new TextEncoder();let folded=rows.map(row=>{let out='',count=0;for(const ch of row){let n=encoder.encode(ch).length;if(count+n>73){out+='\r\n ';count=1}out+=ch;count+=n}return out}).join('\r\n');download('richard-endurance-2027.ics',folded,'text/calendar')}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='week')week=monday(selected);render()});buildPlan();render();
